<?php require_once __DIR__.'/../config/config.php'; require_once __DIR__.'/../config/auth.php'; require_login(); $page_title='Tambah Bukti'; if($_SERVER['REQUEST_METHOD']==='POST'){ $judul=trim($_POST['judul']??'');$jenis=$_POST['jenis']??'O';$tanggal=$_POST['tanggal_bukti']??date('Y-m-d'); if(!empty($_FILES['file']['name'])){$dir=__DIR__.'/../uploads';if(!is_dir($dir))mkdir($dir,0775,true);$ext=strtolower(pathinfo($_FILES['file']['name'],PATHINFO_EXTENSION));$name=uniqid('bukti_',true).'.'.$ext;move_uploaded_file($_FILES['file']['tmp_name'],$dir.'/'.$name);$st=$pdo->prepare('INSERT INTO bukti_implementasi(jenis,judul,tanggal_bukti,filename,original_name,created_by) VALUES(?,?,?,?,?,?)');$st->execute([$jenis,$judul,$tanggal,$name,$_FILES['file']['name'],$_SESSION['user']['id']]);header('Location:index.php');exit;}} require __DIR__.'/../partials/header.php'; ?><h2>Tambah Bukti</h2><div class="card shadow-sm border-0"><div class="card-body"><form method="post" enctype="multipart/form-data"><div class="mb-3"><label>Jenis</label><select class="form-select" name="jenis"><option value="R">R - Regulasi</option><option value="D">D - Dokumen/Bukti</option><option value="O">O - Observasi/Implementasi</option></select></div><div class="mb-3"><label>Judul</label><input class="form-control" name="judul" required></div><div class="mb-3"><label>Tanggal Bukti</label><input class="form-control" type="date" name="tanggal_bukti" value="<?=date('Y-m-d')?>"></div><div class="mb-3"><label>File</label><input class="form-control" type="file" name="file" required></div><button class="btn btn-success">Simpan</button></form></div></div><?php require __DIR__.'/../partials/footer.php';